    {
      name: 'text_transform',
      description: 'Transform text using the specified mode (uppercase, lowercase, or slug).',
      inputSchema: {
        type: 'object',
        properties: {
          text: { type: 'string', description: 'The text to transform.' },
          mode: {
            type: 'string',
            enum: VALID_MODES,
            description: 'Transform mode: uppercase, lowercase, or slug.',
          },
          trim: {
            type: 'boolean',
            default: true,
            description: 'Whether to trim surrounding whitespace before transforming. Defaults to true.',
          },
        },
        required: ['text', 'mode'],
        additionalProperties: false,
      },
    },
  ];
}

function slugify(text) {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

export async function callTool(name, args) {
  if (name !== 'text_transform') {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }

  const { text, mode, trim, ...extra } = args;

  if (Object.keys(extra).length > 0) {
    const keys = Object.keys(extra).join(', ');
    throw new Error(`Unexpected arguments: ${keys}`);
  }

  if (typeof text !== 'string') {
    throw new Error('Argument "text" is required and must be a string');
  }

  if (typeof mode !== 'string' || !VALID_MODES.includes(mode)) {
    throw new Error(`Argument "mode" must be one of: ${VALID_MODES.join(', ')}`);
  }

  const shouldTrim = trim === undefined ? true : trim;
  if (typeof shouldTrim !== 'boolean') {
    throw new Error('Argument "trim" must be a boolean');
  }

  let value = text;
  if (shouldTrim) {
    value = value.trim();
  }

  switch (mode) {
    case 'uppercase':
      value = value.toUpperCase();
      break;
    case 'lowercase':
      value = value.toLowerCase();
      break;
    case 'slug':
      value = slugify(value);
      break;
  }

  return { content: [{ type: 'text', text: value }] };
}

